import glob,os,re,sys
src='/usr/share/icons/breeze-dark'; out=sys.argv[1]
idx={}
for d in ('22','24','16','32'):
    for p in sorted(glob.glob(f'{src}/*/{d}/*.svg')): idx.setdefault(os.path.basename(p)[:-4],os.path.realpath(p))
M={
'krunner':'system-search search','plasma-search':'search','ktip':'help-about documentinfo','preferences-desktop':'configure','preferences-desktop-accessibility':'preferences-desktop-accessibility-symbolic','preferences-desktop-activities':'activities','preferences-desktop-animations':'media-playback-start','preferences-desktop-baloo':'document-preview search','preferences-desktop-color':'color-picker fill-color','preferences-desktop-cursors':'edit-select pointer input-mouse-symbolic cursor-arrow','preferences-desktop-default-applications':'favorite bookmarks emblem-default-symbolic','preferences-desktop-display':'monitor video-display-symbolic computer-symbolic','preferences-desktop-display-randr':'preferences-desktop-display-randr-symbolic','preferences-desktop-effects':'tools-wizard','preferences-desktop-feedback':'dialog-messages','preferences-desktop-filetype-association':'document-properties','preferences-desktop-font':'dialog-text-and-font font format-text-bold','preferences-desktop-font-installer':'font','preferences-desktop-gaming':'input-gamepad-symbolic input-gamepad','preferences-desktop-icons':'view-list-icons view-grid-symbolic','preferences-desktop-keyboard':'input-keyboard-symbolic input-keyboard','preferences-desktop-keyboard-shortcut':'preferences-desktop-keyboard-shortcut-symbolic','preferences-desktop-locale':'preferences-desktop-locale-symbolic','preferences-desktop-mouse':'input-mouse-symbolic input-mouse','preferences-desktop-multimedia':'emblem-videos-symbolic media-playback-start','preferences-desktop-notification-bell':'notifications-symbolic','preferences-desktop-peripherals':'computer-symbolic input-mouse-symbolic','preferences-desktop-plasma-theme':'plasma-symbolic plasma draw-brush','preferences-desktop-search':'search','preferences-desktop-sound':'audio-volume-high-symbolic','preferences-desktop-tablet':'input-tablet-symbolic input-tablet document-edit','preferences-desktop-theme-applications':'draw-brush','preferences-desktop-theme-global':'preferences-desktop-theme-global-symbolic','preferences-desktop-theme-windowdecorations':'window','preferences-desktop-thunderbolt':'flash quickopen','preferences-desktop-touchpad':'input-touchpad-symbolic input-touchpad','preferences-desktop-touchscreen':'input-touchscreen input-touchscreen-symbolic transform-browse','preferences-desktop-user':'user-symbolic user','preferences-desktop-user-password':'lock object-locked','preferences-desktop-virtual':'virtual-desktops virtual-desktops-symbolic','preferences-desktop-wallpaper':'viewimage view-preview','preferences-online-accounts':'internet-services globe','preferences-security':'preferences-security-symbolic','preferences-security-firewall':'security-high-symbolic security-high','preferences-system-bluetooth':'network-bluetooth-symbolic','preferences-system-disks':'drive-harddisk-symbolic drive-harddisk','preferences-system-login':'im-user system-log-out','preferences-system-network':'preferences-system-network-symbolic','preferences-system-network-connection':'network-connect','preferences-system-network-proxy':'network-server-symbolic network-server','preferences-system-power-management':'battery-060-symbolic battery-060','preferences-system-session-services':'run-build system-run','preferences-system-splash':'view-refresh','preferences-system-tabbox':'window-duplicate view-split-left-right','preferences-system-time':'clock','preferences-system-users':'preferences-system-users-symbolic','preferences-system-windows':'window','preferences-system-windows-actions':'window-duplicate','preferences-web-browser-shortcuts':'globe internet-services','xorg':'window','redshift-status-on':'redshift-status-on-symbolic'}
own=out+'/tray'; os.makedirs(out+'/settings',exist_ok=True); miss=[]
for n,c in M.items():
    p=None
    for k in c.split():
        if os.path.exists(f'{own}/{k}.svg'): p=f'{own}/{k}.svg'; break
        if k in idx: p=idx[k]; break
    if not p: miss.append(n); continue
    s=open(p,encoding='utf8').read()
    open(f'{out}/settings/{n}.svg','w').write(s)
    print(n,'<-',os.path.basename(p))
print('MISSING',miss)
t=open(out+'/index.theme').read()
if 'settings' not in t:
    t=t.replace('Directories=tray','Directories=tray,settings')+'\n[settings]\nSize=22\nMinSize=8\nMaxSize=256\nType=Scalable\nContext=Preferences\n'
    open(out+'/index.theme','w').write(t)
